contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker != address(0), "maker zero");
        require(maker != address(this), "maker is test");
        require(duration < 10_000 days, "duration too long");
        require(expiration > block.timestamp, "order expired");

        C.Order memory order;
        order.maker = maker;
        order.isCall = false;
        order.isLong = true;
        order.baseAsset = c.weth();
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        address payable wethPayable = payable(c.weth());
        IWETH weth = IWETH(wethPayable);
        (bool deposited,) = address(weth).call{value: premium}(abi.encodeWithSignature("deposit()"));
        require(deposited, "weth deposit failed");
        weth.approve(address(c), premium);

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeOrderHash = c.hashOppositeOrder(order);
        uint256 longPositionId = uint256(orderHash);
        uint256 shortPositionId = uint256(oppositeOrderHash);

        uint256 beforeTestBalance = weth.balanceOf(address(this));
        uint256 beforeMakerBalance = weth.balanceOf(maker);

        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 positionId = c.fillOrder(order, "", floorAssetTokenIds);

        assert(
            positionId == shortPositionId &&
            weth.balanceOf(maker) == beforeMakerBalance + premium &&
            weth.balanceOf(address(this)) == beforeTestBalance - premium
        );
    }

    receive() external payable {}
}

