contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration
    ) public payable {
        require(maker != address(0), "maker zero");
        require(expiration > block.timestamp, "expiration in past");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: uint256(keccak256(abi.encode(maker, baseAsset, strike, premium, duration, expiration))),
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        require(!c.cancelledOrders(orderHash), "already cancelled");

        c.cancel(order);

        bool fillReverted;
        try c.fillOrder(order, new bytes(0), new uint256[](0)) {
            fillReverted = false;
        } catch {
            fillReverted = true;
        }

        assert(c.cancelledOrders(orderHash) && fillReverted);
    }
}

