contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bool isCall,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address whitelistAddr,
        uint256 floorTokenId
    ) public payable {
        require(expiration > block.timestamp, "Expiration must not have passed");
        require(duration < 10_000 days, "Duration too long");
        require(whitelistAddr == address(this), "Whitelist entry must be this contract");

        address base = c.weth();
        c.setBaseURI("test/");
        c.setFee(0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: true,
            baseAsset: base,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        c.cancel(order);

        uint256 longId = uint256(c.hashOrder(order));
        uint256 shortId = uint256(c.hashOppositeOrder(order));

        require(longId != shortId, "Hash collision");

        c.fillOrder(order, hex"", new uint256[](0));

        uint256 ownerAfter = uint256(uint160(c.ownerOf(longId)));
        uint256 senderAfter = uint256(uint160(c.ownerOf(shortId)));

        assert(ownerAfter == uint256(uint160(address(this))) && senderAfter == uint256(uint160(address(this))) && longId != shortId);
    }

    receive() external payable {}
}

