contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets
    ) public {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bool beforeCancelled = c.cancelledOrders(orderHash);

        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterCancelled = c.cancelledOrders(orderHash);

        assert(
            (maker == address(this) && !reverted && !beforeCancelled && afterCancelled) ||
            (maker != address(this) && reverted && afterCancelled == beforeCancelled)
        );
    }

    receive() external payable {}
}

