        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        uint256[] memory floorAssetTokenIds,
        bytes memory signature
    ) public payable {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256 beforeBalance = address(this).balance;
        uint256 beforeWethBalance = address(baseAsset).balance;
        uint256 beforeCBaseBalance = address(baseAsset).balance;

        uint256 positionId;
        bool reverted;
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            positionId = pid;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // If the order is long, the maker must have transferred premium to the taker (this contract).
            // We cannot directly read the maker's balance; instead we observe that the contract's baseAsset balance
            // decreased by exactly premium when paying in ERC20, or its ETH balance decreased by msg.value.
            // The general rule: the premium is always paid by the maker and received by the taker.
            // For the taker (this contract), its baseAsset balance should have increased by premium if paid in ERC20,
            // or its ETH balance should have decreased by msg.value if paid in ETH (and then converted to WETH for the maker).
            // We assert that the taker received the position token.
            assert(c.ownerOf(positionId) == address(this));
        } else {
            assert(true);
        }
    }
}

