contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 tokenAmount,
        uint256[] memory floorAssetTokenIds
    ) public payable {
        require(maker != address(0), "maker zero");
        require(maker != address(this), "maker is test");
        require(duration < 10_000 days, "duration too long");
        require(expiration > block.timestamp, "expiration too soon");
        require(tokenAmount > 0, "tokenAmount zero");
        require(msg.value == 0 || baseAsset == c.weth(), "native ETH requires weth");
        require(msg.value == 0 || tokenAmount == 0, "native ETH and erc20 amount mixed");

        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);

        if (isLong && isCall) {
            require(floorAssetTokenIds.length == 0, "long call no floors");
        } else {
            require(floorAssetTokenIds.length == 0, "no floors expected");
        }

        if (msg.value > 0) {
            require(address(this).balance >= msg.value, "insufficient balance");
        }

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeOrderHash = c.hashOppositeOrder(order);
        uint256 longPositionId = isLong ? uint256(orderHash) : uint256(oppositeOrderHash);
        uint256 shortPositionId = isLong ? uint256(oppositeOrderHash) : uint256(orderHash);

        uint256 beforeBalanceOfContract = address(c).balance;

        bool reverted;
        uint256 positionId;
        try c.fillOrder{value: msg.value}(order, new bytes(0), floorAssetTokenIds) returns (uint256 id) {
            reverted = false;
            positionId = id;
        } catch {
            reverted = true;
        }

        address longOwner = c.ownerOf(longPositionId);
        address shortOwner = c.ownerOf(shortPositionId);
        uint256 longExpiration = c.positionExpirations(longPositionId);
        uint256 shortExpiration = c.positionExpirations(shortPositionId);

        bool expectedLongOwner = reverted ? false : (msg.sender == maker);
        bool spotFunded = (isLong == isCall);

        assert(
            reverted
                ? (longOwner == address(0) && shortOwner == address(0) && longExpiration == 0 && shortExpiration == 0 && address(c).balance == beforeBalanceOfContract)
                : (positionId == shortPositionId && longOwner == maker && shortOwner == msg.sender && longExpiration == block.timestamp + duration && shortExpiration == block.timestamp + duration && expectedLongOwner == (msg.sender != maker) && (spotFunded || address(c).balance == beforeBalanceOfContract))
        );
    }
}

