    constructor(C _c) { c = _c; }

    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        bool isCall,
        bool isLong
    ) public payable {
        require(maker != address(0), "maker zero");
        require(baseAsset != address(0), "baseAsset zero");
        require(duration < 10_000 days, "duration too long");
        require(block.timestamp < expiration, "expiration not in future");

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        uint256 longTokenId = uint256(orderHash);
        uint256 shortTokenId = uint256(c.hashOppositeOrder(order));

        bytes memory signature = new bytes(0);

        address longOwnerBefore;
        bool longOwnerRevertedBefore;
        try c.ownerOf(isLong ? longTokenId : shortTokenId) returns (address o) {
            longOwnerBefore = o;
        } catch {
            longOwnerRevertedBefore = true;
        }

        address shortOwnerBefore;
        bool shortOwnerRevertedBefore;
        try c.ownerOf(isLong ? shortTokenId : longTokenId) returns (address o) {
            shortOwnerBefore = o;
        } catch {
            shortOwnerRevertedBefore = true;
        }

        address[] memory ownerHolder = new address[](2);
        bool[] memory revertedHolder = new bool[](2);

        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 positionId) {
            ownerHolder[0] = c.ownerOf(isLong ? longTokenId : shortTokenId);
            revertedHolder[0] = false;
            ownerHolder[1] = c.ownerOf(isLong ? shortTokenId : longTokenId);
            revertedHolder[1] = false;
        } catch {
            revertedHolder[0] = true;
            revertedHolder[1] = true;
        }

        bool filledLast;
        bool revertedLast;

        if (isLong) {
            filledLast = ownerHolder[0] == maker;
            revertedLast = revertedHolder[0];
        } else {
            filledLast = ownerHolder[1] == maker;
            revertedLast = revertedHolder[1];
        }

        assert(
            (longOwnerBefore == address(0) && shortOwnerBefore == address(0) && revertedHolder[0] && revertedHolder[1]) ||
            (revertedHolder[0] == false && ownerHolder[0] != address(0) && revertedHolder[1] == false && ownerHolder[1] != address(0)) ||
            (revertedLast == false && filledLast)
        );
    }

    receive() external payable {}
}

